import React from "react";

/**
 * RoomSummaryCard
 * Displays a structured AI room summary generated by DevAgent inside the chat feed.
 *
 * Props:
 * - title: Card heading (default: "Room summary")
 * - roomName: Active room label shown in uppercase metadata (e.g., "Front-end")
 * - dateLabel: Date string shown beside room name (e.g., "November 9")
 * - points: Array of { label: string, text: string } items (Focus, Decision, Next step)
 * - footerNote: Subtle caption explaining the summary source
 */
export default function RoomSummaryCard({
    title = "Room summary",
    roomName = "Front-end",
    dateLabel = "Today",
    points = [],
    footerNote = "Based on the current room conversation",
}) {
    return (
        <div className="dr-card dr-summary-card">
            {/* Header title and uppercase room/date metadata */}
            <div className="dr-card-title">{title}</div>
            <div className="dr-card-meta">
                {roomName.toUpperCase()} &middot; {dateLabel.toUpperCase()}
            </div>

            {/* Key summary takeaways rendered as a clean bulleted list */}
            <ul className="dr-summary-list">
                {points.map((item, idx) => (
                    <li key={idx} className="dr-summary-item">
                        {item.label ? <strong>{item.label}: </strong> : null}
                        <span>{item.text}</span>
                    </li>
                ))}
            </ul>

            {/* Source context caption at the bottom of the card */}
            {footerNote && <div className="dr-card-footer">{footerNote}</div>}
        </div>
    );
}